import golden from './queryex-print-golden.json';
import { tmQx, tmQxInsert, tmQxPrint, type TmQx } from './tm-qx';

// The client's printer against the engine's canonical printer: the golden
// the engine writes is the authority (regenerated by the command in its
// `regenerate` member); the builder's checks and the insertion rule are
// pinned below.

describe('tmQxPrint', () => {
  it.each(golden.rows.map((row) => [row.name, row] as const))('prints as the engine does: %s', (_, row) => {
    expect(tmQxPrint(row.expression as TmQx)).toBe(row.text);
  });

  it('prints the worked examples', () => {
    const p = tmQx.path('CreditLimit');
    expect(tmQxPrint(tmQx.and(tmQx.ge(p, tmQx.num('100000')), tmQx.le(p, tmQx.num('500000'))))).toBe(
      'CreditLimit >= 100000 and CreditLimit <= 500000',
    );
    expect(
      tmQxPrint(tmQx.or(tmQx.call('contains', tmQx.path('Name'), tmQx.str("O'Neil")), tmQx.eq(tmQx.path('Code'), tmQx.str('7')))),
    ).toBe("contains(Name, 'O''Neil') or Code = '7'");
  });

  it('brackets a reserved name and refuses a name containing a closing bracket', () => {
    expect(tmQxPrint(tmQx.path('not.Order'))).toBe('[not].Order');
    expect(() => tmQxPrint({ kind: 'path', segments: ['a]b'] })).toThrow(TypeError);
    expect(() => tmQx.path('a]b')).toThrow(TypeError);
    expect(() => tmQx.param('')).toThrow(TypeError);
  });

  it('refuses a number node that is not decimal text', () => {
    expect(() => tmQxPrint({ kind: 'number', value: '1e3' })).toThrow(TypeError);
  });

  it('refuses an empty membership list the builder never makes', () => {
    expect(() => tmQxPrint({ kind: 'in', value: tmQx.path('x'), items: [] })).toThrow(TypeError);
  });
});

describe('tmQx', () => {
  describe('num', () => {
    it('writes numbers without an exponent', () => {
      expect(tmQxPrint(tmQx.num(1e21))).toBe('1000000000000000000000');
      expect(tmQxPrint(tmQx.num(1.5e-7))).toBe('0.00000015');
      expect(tmQxPrint(tmQx.num(0.25))).toBe('0.25');
    });

    it('writes a negative number as the negation of its magnitude, as the engine reads it', () => {
      expect(tmQx.num(-5)).toEqual({ kind: 'negate', operand: { kind: 'number', value: '5' } });
      expect(tmQx.num('-1.50')).toEqual({ kind: 'negate', operand: { kind: 'number', value: '1.50' } });
      expect(tmQx.num('-0')).toEqual({ kind: 'number', value: '0' });
      expect(tmQxPrint(tmQx.lt(tmQx.path('Amount'), tmQx.num(-5)))).toBe('Amount < -5');
    });

    it('refuses a number beyond 15 significant digits, and takes its text instead', () => {
      expect(() => tmQx.num(2 ** 53)).toThrow(RangeError);
      expect(() => tmQx.num(0.1 + 0.2)).toThrow(RangeError);
      expect(tmQxPrint(tmQx.num(123456789012345))).toBe('123456789012345');
      expect(tmQxPrint(tmQx.num('9007199254740993'))).toBe('9007199254740993');
    });

    it('refuses digits past the engine’s 38, leading zeros aside', () => {
      expect(() => tmQx.num(1e-40)).toThrow(RangeError);
      expect(() => tmQx.num('1'.repeat(39))).toThrow(RangeError);
      expect(() => tmQx.num(`-0.${'0'.repeat(38)}1`)).toThrow(RangeError);
      expect(tmQxPrint(tmQx.num('1'.repeat(38)))).toBe('1'.repeat(38));
      expect(tmQxPrint(tmQx.num(`000${'1'.repeat(38)}`))).toBe(`000${'1'.repeat(38)}`);
      expect(tmQxPrint(tmQx.num(`0.${'1'.repeat(38)}`))).toBe(`0.${'1'.repeat(38)}`);
    });

    it('refuses a number that is not finite and text that is not decimal', () => {
      expect(() => tmQx.num(Number.NaN)).toThrow(RangeError);
      expect(() => tmQx.num(Number.POSITIVE_INFINITY)).toThrow(RangeError);
      for (const text of ['1e3', '+1', '.5', '5.', '0x10', '1,000', '', ' 1', String.fromCharCode(0x661)]) {
        expect(() => tmQx.num(text)).toThrow(TypeError);
      }
    });
  });

  describe('literal', () => {
    it('writes each type as the engine coerces it', () => {
      expect(tmQxPrint(tmQx.literal('string', "O'Neil"))).toBe("'O''Neil'");
      expect(tmQxPrint(tmQx.literal('enum', 'Service'))).toBe("'Service'");
      expect(tmQxPrint(tmQx.literal('guid', '0f8fad5b-d9cb-469f-a165-70867728950e'))).toBe("'0f8fad5b-d9cb-469f-a165-70867728950e'");
      expect(tmQxPrint(tmQx.literal('integer', '1012'))).toBe('1012');
      expect(tmQxPrint(tmQx.literal('decimal', '0.2500'))).toBe('0.2500');
      expect(tmQxPrint(tmQx.literal('bool', false))).toBe('false');
      expect(tmQxPrint(tmQx.literal('date', '2026-03-01'))).toBe("'2026-03-01'");
      expect(tmQxPrint(tmQx.literal('datetime', '2026-03-01T08:05'))).toBe("'2026-03-01T08:05:00'");
      expect(tmQxPrint(tmQx.literal('datetime', '2026-03-01'))).toBe("'2026-03-01T00:00:00'");
      expect(tmQxPrint(tmQx.literal('instant', '2026-03-01T08:05:00+03:00'))).toBe("'2026-03-01T08:05:00+03:00'");
      expect(tmQxPrint(tmQx.literal('instant', Date.UTC(2025, 11, 31, 21)))).toBe("'2025-12-31T21:00:00+00:00'");
      expect(tmQxPrint(tmQx.literal('instant', new Date(Date.UTC(2026, 0, 1, 0, 0, 0, 250))))).toBe("'2026-01-01T00:00:00.250+00:00'");
      expect(tmQxPrint(tmQx.literal('date', null))).toBe('null');
    });

    it('refuses a value that is not one of the type', () => {
      expect(() => tmQx.literal('integer', '1.5')).toThrow(TypeError);
      expect(() => tmQx.literal('integer', 1.5)).toThrow(TypeError);
      expect(() => tmQx.literal('bool', 'true')).toThrow(TypeError);
      expect(() => tmQx.literal('date', '2026-02-30')).toThrow(TypeError);
      expect(() => tmQx.literal('date', '2026-3-1')).toThrow(TypeError);
      expect(() => tmQx.literal('datetime', '2026-03-01T24:00')).toThrow(TypeError);
      expect(() => tmQx.literal('datetime', '2026-03-01T08:00:00Z')).toThrow(TypeError);
      expect(() => tmQx.literal('instant', '2026-03-01T08:00:00')).toThrow(TypeError);
      expect(() => tmQx.literal('instant', Number.NaN)).toThrow(TypeError);
    });

    it('refuses the types with no literal', () => {
      expect(() => tmQx.literal('time', '08:00')).toThrow(TypeError);
      expect(() => tmQx.literal('json', '{}')).toThrow(TypeError);
      expect(() => tmQx.literal('binary', 'AA==')).toThrow(TypeError);
    });
  });

  describe('and, or and in', () => {
    it('skips nulls, and stands for true or false when nothing is left', () => {
      expect(tmQxPrint(tmQx.and(null, tmQx.path('a'), null))).toBe('a');
      expect(tmQxPrint(tmQx.and())).toBe('true');
      expect(tmQxPrint(tmQx.or(null))).toBe('false');
    });

    it('chains to the left, so a chain prints with no parentheses', () => {
      expect(tmQxPrint(tmQx.or(tmQx.path('a'), tmQx.path('b'), tmQx.path('c')))).toBe('a or b or c');
      expect(tmQxPrint(tmQx.and(tmQx.or(tmQx.path('a'), tmQx.path('b')), tmQx.path('c')))).toBe('(a or b) and c');
    });

    it('stands for false over no items', () => {
      expect(tmQxPrint(tmQx.in(tmQx.path('a'), []))).toBe('false');
      expect(tmQxPrint(tmQx.in(tmQx.path('a'), [tmQx.num(1), tmQx.num(2)]))).toBe('a in (1, 2)');
    });

    it('prints absence and presence', () => {
      expect(tmQxPrint(tmQx.isNull(tmQx.path('DueDate')))).toBe('DueDate is null');
      expect(tmQxPrint(tmQx.not(tmQx.isNull(tmQx.path('DueDate'), true)))).toBe('not DueDate is not null');
    });
  });

  describe('raw', () => {
    it('prints server text in parentheses, so precedence cannot reach into it', () => {
      expect(tmQxPrint(tmQx.and(tmQx.raw('a or b'), tmQx.path('c')))).toBe('(a or b) and c');
      expect(tmQxPrint(tmQx.not(tmQx.raw('x'))))
        .toBe('not (x)');
    });

    it('refuses text that does not lex or cannot be grouped', () => {
      for (const text of ['', '   ', "a = 'b", 'a) or (b', 'a # b', '(a']) {
        expect(() => tmQx.raw(text)).toThrow(TypeError);
      }
    });
  });
});

describe('tmQxInsert', () => {
  it('inserts at a token boundary as it stands, with the range it occupies', () => {
    expect(tmQxInsert('a = ', 4, 'b')).toEqual({ text: 'a = b', start: 4, end: 5 });
    expect(tmQxInsert('f()', 2, 'x')).toEqual({ text: 'f(x)', start: 2, end: 3 });
  });

  it('moves an insertion inside a token to the token end', () => {
    expect(tmQxInsert('Amount', 3, ' + 1')).toEqual({ text: 'Amount + 1', start: 6, end: 10 });
    expect(tmQxInsert("Name = 'abc' or", 9, ' x')).toEqual({ text: "Name = 'abc' x or", start: 12, end: 14 });
    expect(tmQxInsert('a = 123', 5, '')).toEqual({ text: 'a = 123', start: 7, end: 7 });
  });

  it('separates the insertion from a name, a digit or a closing parenthesis it would touch', () => {
    expect(tmQxInsert('a and', 5, 'b')).toEqual({ text: 'a and b', start: 6, end: 7 });
    expect(tmQxInsert('f(x)', 4, 'Code')).toEqual({ text: 'f(x) Code', start: 5, end: 9 });
    expect(tmQxInsert('12', 2, 'x')).toEqual({ text: '12 x', start: 3, end: 4 });
    expect(tmQxInsert('a', 0, 'Parent.Code')).toEqual({ text: 'Parent.Code a', start: 0, end: 11 });
    expect(tmQxInsert('x = ', 4, '@From')).toEqual({ text: 'x = @From', start: 4, end: 9 });
  });

  it('adds no space beside an operator, a separator or white space', () => {
    expect(tmQxInsert('a', 1, '+')).toEqual({ text: 'a+', start: 1, end: 2 });
    expect(tmQxInsert('f(a,)', 4, 'b')).toEqual({ text: 'f(a,b)', start: 4, end: 5 });
    expect(tmQxInsert('a ', 2, 'b')).toEqual({ text: 'a b', start: 2, end: 3 });
  });

  it('never lets the insertion run into the token beside it', () => {
    expect(tmQxInsert("'a'", 3, "'b'")).toEqual({ text: "'a' 'b'", start: 4, end: 7 });
    expect(tmQxInsert('a <', 3, '= 1')).toEqual({ text: 'a < = 1', start: 4, end: 7 });
    expect(tmQxInsert('a.', 2, '5')).toEqual({ text: 'a. 5', start: 3, end: 4 });
    expect(tmQxInsert('x', 0, "'b'")).toEqual({ text: "'b' x", start: 0, end: 3 });
  });

  it('clamps the caret to the text', () => {
    expect(tmQxInsert('a', 9, ' b')).toEqual({ text: 'a b', start: 1, end: 3 });
    expect(tmQxInsert('a', -4, 'b ')).toEqual({ text: 'b a', start: 0, end: 2 });
  });

  it('never splits an unterminated string or a malformed number', () => {
    expect(tmQxInsert("a = 'ab", 6, 'x')).toEqual({ text: "a = 'ab x", start: 8, end: 9 });
    expect(tmQxInsert('a = 1e3', 5, 'x').text).toBe('a = 1e3 x');
  });
});
